import { bech32CreateChecksum, bech32VerifyChecksum } from './bech32/index.mjs';

const PROG = 'test10.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B`;

function printHelp() {
  console.log(USAGE);
  console.log('');
  console.log('options:');
  console.log('  -h, --help  show this help message and exit');
  console.log('  --a A');
  console.log('  --b B');
}

function parseArgs(argv) {
  const result = {};
  const missing = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      printHelp();
      process.exit(0);
    }
    let name = null;
    let value = null;
    if (arg === '--a' || arg === '--b') {
      name = arg.slice(2);
      value = argv[++i];
    } else if (arg.startsWith('--a=')) {
      name = 'a';
      value = arg.slice(4);
    } else if (arg.startsWith('--b=')) {
      name = 'b';
      value = arg.slice(4);
    }
    if (name !== null) {
      result[name] = value;
    }
  }
  if (result.a === undefined) missing.push('--a');
  if (result.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    console.error(USAGE);
    console.error(`${PROG}: error: the following arguments are required: ${missing.join(', ')}`);
    process.exit(2);
  }
  return result;
}

const args = parseArgs(process.argv.slice(2));
const data = args.b.split(',').map(s => parseInt(s, 10));
const checksum = bech32CreateChecksum(args.a, data);
const isValid = bech32VerifyChecksum(args.a, data.concat(checksum));
console.log('[' + checksum.join(', ') + ']');
console.log(isValid ? 'True' : 'False');

