// Minimal local copy of the bech32 reference library (Pieter Wuille's
// reference implementation), for TESTING ONLY while /output/bech32/index.mjs
// is pending from the other agent.

const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

function bech32Polymod(values) {
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      chk ^= ((b >> i) & 1) ? GEN[i] : 0;
    }
  }
  return chk;
}

function bech32HrpExpand(s) {
  const ret = [];
  for (const c of s) ret.push(c.charCodeAt(0) >> 5);
  ret.push(0);
  for (const c of s) ret.push(c.charCodeAt(0) & 31);
  return ret;
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === 1;
}

export function bech32CreateChecksum(hrp, data) {
  const values = bech32HrpExpand(hrp).concat(data);
  const polymod = bech32Polymod(values.concat([0, 0, 0, 0, 0, 0])) ^ 1;
  const ret = [];
  for (let i = 0; i < 6; i++) {
    ret.push((polymod >> (5 * (5 - i))) & 31);
  }
  return ret;
}

